const inp = $input.item.json;
const question = inp['Вопрос'] || '';
const answer = inp['Ответ'] || '';
const codeSaid = inp['КодСказал'] || '';
const MAP = [
    {match: "Можно ли перенести занят", kb_id: "kb2", kb_text: "kb2 · Перенос занятия: Перенести конкретное занятие можно не позднее чем за 24 часа до его начала — через личный кабинет (кнопка «Перенести») или сообщением администратору. Позже 24 часов занятие считается использованным.", kb_keyword: "24 час", kb_numbers: ["24"]},
    {match: "Когда мне вернут деньги ", kb_id: "kb4", kb_text: "kb4 · Возврат денег: Возврат оформляется в течение 10 рабочих дней на карту, с которой была оплата. Для сумм выше 3000 рублей решение проходит через руководителя, это дольше стандартного срока.", kb_keyword: "10 рабочих дней", kb_numbers: ["10", "3000"]},
    {match: "Как мне попасть на перес", kb_id: "kb5", kb_text: "kb5 · Пересдача пропущенного занятия: Пересдачи идут каждую вторую субботу месяца, расписание публикуется в объявлениях личного кабинета за неделю.", kb_keyword: "вторую субботу", kb_numbers: []},
    {match: "Когда появится сертифика", kb_id: "kb7", kb_text: "kb7 · Сертификат: Электронный сертификат формируется автоматически и появляется в личном кабинете в течение 5 рабочих дней после последнего занятия курса.", kb_keyword: "5 рабочих дней", kb_numbers: ["5"]},
    {match: "Хочу перейти на другой к", kb_id: "kb8", kb_text: "kb8 · Перевод на другой курс: Перевод возможен при наличии мест на новом курсе; разница в стоимости пересчитывается администратором индивидуально.", kb_keyword: "перевод", kb_numbers: []},
    {match: "Как связаться с преподав", kb_id: "kb10", kb_text: "kb10 · Связь с преподавателем: Написать конкретному преподавателю можно через раздел «Сообщения» личного кабинета, ответ приходит в течение одного рабочего дня.", kb_keyword: "Сообщения", kb_numbers: []}
];
let picked = null;
for (const m of MAP) { if (question.includes(m.match)) { picked = m; break; } }
if (!picked) picked = MAP[0];
return { json: {
  question, answer, code_said: codeSaid,
  kb_id: picked.kb_id, kb_text: picked.kb_text, kb_keyword: picked.kb_keyword,
  kb_numbers: picked.kb_numbers,
} };
